import {Machine,validateProject} from './machine.mjs';
self.onmessage=({data})=>{try{const p=validateProject(data.project),rate=44100,body=Math.round(64*60/p.bpm/4*rate),tail=rate*4,total=body+tail,m=new Machine(rate,p),buffer=new ArrayBuffer(44+total*2),dv=new DataView(buffer);const str=(p,s)=>{for(let i=0;i<s.length;i++)dv.setUint8(p+i,s.charCodeAt(i));};str(0,'RIFF');dv.setUint32(4,36+total*2,true);str(8,'WAVE');str(12,'fmt ');dv.setUint32(16,16,true);dv.setUint16(20,1,true);dv.setUint16(22,1,true);dv.setUint32(24,rate,true);dv.setUint32(28,rate*2,true);dv.setUint16(32,2,true);dv.setUint16(34,16,true);str(36,'data');dv.setUint32(40,total*2,true);m.start();for(let i=0;i<total;i++){if(i===body)m.stop();let v=m.sample();if(m.error)throw Error(m.error);let fade=Math.min(1,(total-i)/(rate*.2));dv.setInt16(44+i*2,Math.round(Math.max(-1,Math.min(1,v*.75*fade))*32767),true);}self.postMessage({buffer},[buffer]);}catch(e){self.postMessage({error:e.message});}};
